import { useState } from 'react';

const columnas = [
  { campo: 'nombre', titulo: 'Nombre' },
  { campo: 'edad', titulo: 'Edad' },
  { campo: 'email', titulo: 'Email' },
];

export function TablaUsuarios({ usuarios }) {
  const [orden, setOrden] = useState('nombre');

  const ordenados = usuarios.sort((a, b) =>
    a[orden] > b[orden] ? 1 : -1
  );

  return (
    <table>
      <thead>
        <tr>
          {columnas.map((c) => (
            <th key={c.campo} onClick={() => setOrden(c.campo)}>{c.titulo}</th>
          ))}
        </tr>
      </thead>
      <tbody>
        {ordenados.map((u, index) => (
          <tr key={index}>
            <td>{u.nombre}</td>
            <td>{u.edad}</td>
            <td>{u.email}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}
